    { id=18230, tab=2, tier=4, col=1, name="Demonic Sacrifice", icon="spell_shadow_psychicscream", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Instant. Sacrifices your summoned demon to grant you an effect that lasts 30 min, canceled if you resummon a demon. Imp: Increases your Fire damage by 15%. Voidwalker: Restores 3% of total Health every 4 sec. Succubus: Increases your Shadow damage by 15%. Felhunter: Restores 2% of total Mana every 4 sec." }, grant={ [1]=932929 }, localized={deDE={name="Dämonische Opferung", tooltip={ "Sofort. Opfert Euren beschworenen Dämon und gewährt Euch einen Effekt, der 30 Min. lang anhält und endet, wenn Ihr erneut einen Dämon beschwört. Wichtel: Erhöht Euren Feuerschaden um 15%. Leerwandler: Stellt alle 4 Sek. 3% Eurer gesamten Gesundheit wieder her. Sukkubus: Erhöht Euren Schattenschaden um 15%. Teufelsjäger: Stellt alle 4 Sek. 2% Eures gesamten Manas wieder her." }}} },
    { id=18231, tab=2, tier=4, col=3, name="Improved Firestone", icon="inv_ammo_firetar", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases the bonus Fire damage from Firestones and the Firestone effect by 15%.", "Increases the bonus Fire damage from Firestones and the Firestone effect by 30%." }, localized={deDE={name="Verbesserter Feuerstein", tooltip={ "Erhöht den zusätzlichen Feuerschaden von Feuersteinen und die Wirkung des Feuersteins um 15%.", "Erhöht den zusätzlichen Feuerschaden von Feuersteinen und die Wirkung des Feuersteins um 30%." }}} },
    { id=18232, tab=2, tier=5, col=2, name="Master Demonologist", icon="spell_shadow_shadowpact", maxRank=5, prereqTalent=18228, prereqPoints=25, wired=true, tooltip={ "Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Reduces threat caused by 4%. Voidwalker - Reduces physical damage taken by 2%. Succubus - Increases all damage caused by 2%. Felhunter - Increases all resistances by .2 per level.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Reduces threat caused by 8%. Voidwalker - Reduces physical damage taken by 4%. Succubus - Increases all damage caused by 4%. Felhunter - Increases all resistances by .4 per level.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Reduces threat caused by 12%. Voidwalker - Reduces physical damage taken by 6%. Succubus - Increases all damage caused by 6%. Felhunter - Increases all resistances by .6 per level.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Reduces threat caused by 16%. Voidwalker - Reduces physical damage taken by 8%. Succubus - Increases all damage caused by 8%. Felhunter - Increases all resistances by .8 per level.", "Grants both the Warlock and the summoned demon an effect as long as that demon is active. Imp - Reduces threat caused by 20%. Voidwalker - Reduces physical damage taken by 10%. Succubus - Increases all damage caused by 10%. Felhunter - Increases all resistances by 1 per level." }, localized={deDE={name="Meister der Dämonologie", tooltip={ "Gewährt dem Hexenmeister und seinem beschworenen Dämon einen Effekt, solange dieser Dämon aktiv ist. Wichtel: Verringert die erzeugte Bedrohung um 4%. Leerwandler: Verringert den erlittenen körperlichen Schaden um 2%. Sukkubus: Erhöht sämtlichen verursachten Schaden um 2%. Teufelsjäger: Erhöht alle Widerstände pro Stufe um 0,2.", "Gewährt dem Hexenmeister und seinem beschworenen Dämon einen Effekt, solange dieser Dämon aktiv ist. Wichtel: Verringert die erzeugte Bedrohung um 8%. Leerwandler: Verringert den erlittenen körperlichen Schaden um 4%. Sukkubus: Erhöht sämtlichen verursachten Schaden um 4%. Teufelsjäger: Erhöht alle Widerstände pro Stufe um 0,4.", "Gewährt dem Hexenmeister und seinem beschworenen Dämon einen Effekt, solange dieser Dämon aktiv ist. Wichtel: Verringert die erzeugte Bedrohung um 12%. Leerwandler: Verringert den erlittenen körperlichen Schaden um 6%. Sukkubus: Erhöht sämtlichen verursachten Schaden um 6%. Teufelsjäger: Erhöht alle Widerstände pro Stufe um 0,6.", "Gewährt dem Hexenmeister und seinem beschworenen Dämon einen Effekt, solange dieser Dämon aktiv ist. Wichtel: Verringert die erzeugte Bedrohung um 16%. Leerwandler: Verringert den erlittenen körperlichen Schaden um 8%. Sukkubus: Erhöht sämtlichen verursachten Schaden um 8%. Teufelsjäger: Erhöht alle Widerstände pro Stufe um 0,8.", "Gewährt dem Hexenmeister und seinem beschworenen Dämon einen Effekt, solange dieser Dämon aktiv ist. Wichtel: Verringert die erzeugte Bedrohung um 20%. Leerwandler: Verringert den erlittenen körperlichen Schaden um 10%. Sukkubus: Erhöht sämtlichen verursachten Schaden um 10%. Teufelsjäger: Erhöht alle Widerstände pro Stufe um 1." }}} },
